"use strict";(self.webpackChunkmy_portfolio=self.webpackChunkmy_portfolio||[]).push([[922],{8922:(e,t,a)=>{a.d(t,{BT:()=>d,L1:()=>o,RJ:()=>s,XT:()=>r,_g:()=>n,cR:()=>i,iD:()=>h,ot:()=>l});const o="Samsung Galaxy Note II (SGH-T889V)",n={"showing-my-uncle":{slug:"showing-my-uncle",date:"2009-01-01",dateLabel:"c. 2009",title:"Showing my uncle",caption:"A photograph of a photograph, which is why the file metadata says May 2024 \u2014 the print is far older than the scan of it. Me as a teenager on the couch with an HP laptop across my knees and my uncle stretched out beside me, almost certainly being shown whatever I had just worked out how to make the thing do. It sits somewhere around the first build, and it is the earliest image in this archive.",wide:!0},"den-first-corner":{slug:"den-first-corner",date:"2012-12-25",dateLabel:"December 25, 2012",title:"The corner it started in",caption:"Christmas night, 2012. A Sony Bravia doing duty as a monitor, the tower on the floor with its GTX badge turned deliberately outward, and a laptop running on the carpet because there was no desk for it yet. The fighter-jet print stayed on that wall for years."},"lan-new-years-eve":{slug:"lan-new-years-eve",date:"2012-12-31",dateLabel:"December 31, 2012",title:"New Year's Eve LAN",caption:"New Year's Eve, 2012. Six machines hauled into the basement and set up on folding tables, pizza on paper plates, every tower humming at once. I hosted these because it was the one night the hardware had an audience."},"four-screens-february":{slug:"four-screens-february",date:"2013-02-02",dateLabel:"February 2, 2013",title:"Four panels, one desk",caption:"February 2013. Four displays running simultaneously \u2014 an HDTV pressed into service on the left, a laptop wedged into the middle, a flight stick and headset staged on the right. The consoles live underneath."},"desk-condenser-mic":{slug:"desk-condenser-mic",date:"2013-02-08",dateLabel:"February 8, 2013",title:"The microphone arrives",caption:"A Blue Yeti lands in the middle of the desk, between a Sharp Aquos and a Dell panel, with a Logitech G-series board on the tray below. The first time the setup was built around audio as much as video."},"desk-goes-l-shaped":{slug:"desk-goes-l-shaped",date:"2013-03-29",dateLabel:"March 29, 2013",title:"The desk goes L-shaped",caption:"March 2013. More surface than sense: the desk turns a corner to carry a second workstation on the left wing, a console mid-desk, and the microphone holding its position on the right."},"blue-hour-battlestation":{slug:"blue-hour-battlestation",date:"2013-04-17",dateLabel:"April 17, 2013",title:"Blue hour",caption:"April 2013. Blue LEDs, a pop filter on a boom arm, and the tower lifted off the carpet and parked beside the desk so its drive bays were reachable without crawling under anything."},"the-den-september":{slug:"the-den-september",date:"2013-09-17",dateLabel:"September 17, 2013",title:"The room, coherent",caption:"September 2013. The whole den finally reads as one thing: posters framed and hung, microphone on a boom, a camera on a tripod, the small screen open to Reddit, and a chair worth sitting in for eight hours."},"blood-and-thermal-paste":{slug:"blood-and-thermal-paste",date:"2013-11-30",dateLabel:"November 30, 2013",title:"Blood and thermal paste",caption:"The morning of November 30, 2013. An MSI board mid-install and a thumb opened up on an unfinished case edge. Every build costs a little blood, and you come out of it routing cables with considerably more respect."},"first-liquid-cooling":{slug:"first-liquid-cooling",date:"2013-12-07",dateLabel:"December 7, 2013",title:"First closed loop",caption:"December 7, 2013. The first liquid cooler seated on a CPU \u2014 Corsair pump block, tubing routed up and around the memory, GPU sitting below it. The evening air cooling stopped being enough."},"the-wooden-desk":{slug:"the-wooden-desk",date:"2013-12-16",dateLabel:"December 16, 2013",title:"A real desk",caption:"December 2013. Glass and steel give way to a solid wooden desk. The tower goes up on top where it can actually be seen, headphones hang off the case, and the printer gets demoted to the side table."},"the-workbench":{slug:"the-workbench",date:"2013-12-26",dateLabel:"December 26, 2013",title:"The bench",caption:"Boxing Day, 2013. Two folding tables, a whiteboard, and two machines open at once. This was the bench \u2014 where other people's dead computers came to be made useful again."},"salvage-teardown":{slug:"salvage-teardown",date:"2013-12-26",dateLabel:"December 26, 2013",title:"Salvage, sorted",caption:"The same afternoon, closer in. A stripped board with its slots bare, a 3.5-inch drive, sticks of memory pulled and lined up, a gutted case shell, a loose 80 mm fan. None of this was bought. All of it was somebody else's hand-me-down."},"five-displays":{slug:"five-displays",date:"2013-12-30",dateLabel:"December 30, 2013",title:"Five displays",caption:"December 30, 2013. Five panels lit at once, all carrying the same photograph of the same lake, because the point was never the wallpaper \u2014 it was that they were all working together."},"the-sound-card":{slug:"the-sound-card",date:"2014-01-23",dateLabel:"January 23, 2014",title:"The hinge",caption:"January 2014. A discrete sound card held up before it goes in the slot \u2014 gold-film capacitors, a Dolby block, RCA outputs down the bracket. This specific object is the hinge in the whole story: the point where the computers and the music stopped being two separate interests."},"laptop-stripped-to-board":{slug:"laptop-stripped-to-board",date:"2014-01-25",dateLabel:"January 25, 2014",title:"Down to the board",caption:"A laptop taken all the way down to the bare board: copper heat pipe, blower fan, memory still seated in its slot, its 2.5-inch drive set aside to be reused elsewhere. Teardown as a way of reading how something was designed."},"lan-in-the-dark":{slug:"lan-in-the-dark",date:"2014-01-27",dateLabel:"January 27, 2014",title:"Lights off",caption:"January 2014, lights out. Four of us deep into a session on red backlit keys, one already reclined and gone. The same posters from the daylight photos are still on the wall behind us."},"four-screens-may":{slug:"four-screens-may",date:"2014-05-05",dateLabel:"May 5, 2014",title:"Everything open at once",caption:"May 2014, mid-evening. A music library queued up on the top panel, a games storefront mid-sale beside it, social feeds spread across the bottom two. Four screens because one context was never enough."},"the-crew":{slug:"the-crew",date:"2014-05-05",dateLabel:"May 5, 2014",title:"The crew",caption:"The same night, caught on the webcam. The basement regulars, a whiteboard still covered in whatever we were arguing about, and one of us reading a Captain America comic on the couch.",wide:!0},"first-circuit-lit":{slug:"first-circuit-lit",date:"2014-05-29",dateLabel:"May 29, 2014",title:"It lights",caption:"May 29, 2014. A circuit built by hand on perfboard \u2014 transistor, electrolytic capacitor, trimmer pot, resistor \u2014 and an LED that lit because I told it to. Small, and a completely different category of thing from assembling a computer."},"the-den-panorama":{slug:"the-den-panorama",date:"2014-07-22",dateLabel:"July 22, 2014",title:"The den, entire",caption:"July 2014, shot as a panorama. The finished room: desk and glowing tower on the left, posters, shelves of games and gear, and a couch for whoever turned up. This is the room I disappeared into.",wide:!0},"fan-expo-sword":{slug:"fan-expo-sword",date:"2014-08-29",dateLabel:"August 29, 2014",title:"Nerd at heart, on the record",caption:"Fan Expo, Toronto, August 2014. A replica greatsword in both hands and a Captain America shield in the crate below. I am a nerd at heart and I have never once tried to hide it."},"fan-expo-cosplay":{slug:"fan-expo-cosplay",date:"2014-08-29",dateLabel:"August 29, 2014",title:"On the floor",caption:"The same afternoon out on the convention floor, between two cosplayers in full fabricated armour. The costumes, the comics, the games, the hardware \u2014 all one impulse. Find the thing you love and go all the way in."},"fan-expo-jude":{slug:"fan-expo-jude",date:"2014-08-29",dateLabel:"August 29, 2014",title:"Meeting Jude",caption:"The same Fan Expo, at a booth on the concourse: standing beside a life-size cutout of Jude from 6teen, next to the actor who voiced him. A cartoon I grew up on, and the person behind the voice throwing horns for the photo."},"hamilton-room":{slug:"hamilton-room",date:"2016-01-01",dateLabel:"Hamilton, 2015\u20132016",title:"The setup follows me",caption:"My room in Hamilton during the semester at Mohawk, two friends asleep across the bed at the end of a long night. Three panels, a condenser mic on a boom arm, the tower glowing blue, water bottles and books on the floor. Barely any space and no desk chair \u2014 I used the bed as one. Wherever I went, the setup came with me and rearranged itself to fit."},"first-guitar":{slug:"first-guitar",date:"2016-03-01",dateLabel:"Before Metalworks, c. 2016",title:"The first guitar",caption:"Two of us with guitars in the basement of my childhood house, a small Line 6 combo amp between us. The black one is mine \u2014 the first instrument I ever bought with my own money. This is close to the last time I made music in that house before leaving for Metalworks."},"metalworks-studio-6":{slug:"metalworks-studio-6",date:"2016-09-01",dateLabel:"Metalworks, 2016\u20132017",title:"Studio 6",caption:"One of the rooms at Metalworks: a full large-format console, main monitors soffit-mounted above it, timber diffusion across the ceiling, and a couch for whoever was listening. Walking into a room built entirely around how sound behaves is what opened my eyes to the whole discipline."},"at-the-laptop":{slug:"at-the-laptop",date:"2018-01-01",dateLabel:"The Synth Rider years",title:"White hair, mixer open",caption:"Overhead, mid-session: a mixer and arrangement open across the laptop, bleached hair pulled into a ponytail. I looked far more like a punk rockstar then than I do now, and that was entirely deliberate. Worth keeping in the record purely for how much a person can change."},"the-purple-studio":{slug:"the-purple-studio",date:"2018-08-13",dateLabel:"August 13, 2018 \xb7 11:56 p.m.",title:"The studio we built",caption:"The room my dad and I built together in the basement of his new house. It started as bare cinderblock. Using what I had learned at Metalworks we treated it properly: bass traps in every corner, broadband absorbers on the walls, clouds overhead, acoustic insulation and matting behind and in front of the drywall, diagonal venting so sound could not escape through the ducts, and jambs fitted to the doors so the seals actually closed. Then we balanced the monitors to the room itself. Not a bedroom with foam on the wall \u2014 a real one."},"studio-669-lounge":{slug:"studio-669-lounge",date:"2018-08-19",dateLabel:"August 19, 2018 \xb7 2:37 a.m.",title:"669, from the couch",caption:"Half past two in the morning at 669 on Queen Street, shot from the couch at the back of the room \u2014 my own shoes in the frame, outboard gear glowing in the rack, the live room through the glass. Three floors of studios above a row of storefronts, and completely invisible from the pavement. Nobody walking past would ever have guessed."},"studio-669-sept-8":{slug:"studio-669-sept-8",date:"2018-09-08",dateLabel:"Saturday, September 8, 2018 \xb7 11:46 p.m.",title:'Room 2, the night of "She"',caption:'Room 2 at 669, just before midnight on a Saturday \u2014 the room we always booked. This is the same session that produced the bounce filed as "She", which sits a little further down this page. The photograph and the audio are the same few hours of the same night, recovered separately, seven years apart.'},"studio-669-sept-22":{slug:"studio-669-sept-22",date:"2018-09-22",dateLabel:"Saturday, September 22, 2018 \xb7 10:17 p.m.",title:"Another Saturday, another group",caption:"Two weeks later, same building, different people around the desk: someone tracking into a laptop over a MIDI controller, monitors up, a TV running on the wall, and the rest of the room waiting on the couch behind me. The Saturday booking was a standing fixture that autumn."},"in-n-out-la":{slug:"in-n-out-la",date:"2018-12-02",dateLabel:"December 2, 2018 \xb7 6:15 p.m.",title:"Los Angeles",caption:"Outside an In-N-Out under palm trees on my first evening in Los Angeles, an IHOP sign burning blue across the road. I could not get over it. Somebody else had paid to fly me here to work on music. Standing in that parking lot, it genuinely felt like I had made it."},"la-studio-night":{slug:"la-studio-night",date:"2018-12-05",dateLabel:"December 5, 2018 \xb7 5:30 a.m.",title:"Half five in the morning, LA",caption:"A studio I worked out of in Los Angeles, shot as a panorama at half past five in the morning \u2014 a wall of screens running visuals, three laptops open, and everyone still going. In the room: a friend from high school who taught himself to produce, a friend from music school working in bass music, and a rapper from back home in Canada, all of us out there together.",wide:!0},"setup-2020":{slug:"setup-2020",date:"2020-10-20",dateLabel:"October 20, 2020",title:"Eleven years on",caption:"October 2020. A racing chair, a studio monitor up on a stand, acoustic treatment on the wall behind the desk, a boom arm still within arm's reach, and a game running on the panel. Different hardware entirely. Identical instinct.",wide:!0},"hand-coded-learning-2022":{slug:"hand-coded-learning-2022",date:"2022-02-23",dateLabel:"February 23, 2022",title:"Everything open at once",caption:"February 23, 2022. School was fully remote, the work was still being written by hand, and the browser was part of the toolchain. Visual Studio Code on the left, a working assignment on the right, and Stack Overflow and W3Schools doing the explaining that an LLM could not yet do. The comment in the file records the date: a small, precise snapshot of learning software the slow way."},"xr-lab-whiteboard-2023":{slug:"xr-lab-whiteboard-2023",date:"2023-01-04",dateLabel:"January 4, 2023",title:"The XR Lab wall",caption:"January 4, 2023, in Mohawk College's XR Lab \u2014 the first week of the job, as an XR Developer. The work sat exactly at the intersection I had been moving toward: part software, part game development, part education, with the strange and immediate joy of making something people could step inside.",wide:!0},"ideaworks-cubicles":{slug:"ideaworks-cubicles",date:"2023-01-26",dateLabel:"January 26, 2023 \xb7 2:11 p.m.",title:"The floor nobody sat on",caption:"The IdeaWorks floor: banks of cubicles against an orange wall, every monitor live, every chair empty, and a printed notice taped to each divider. Most of the developers remoted into these machines from home, and the standing instruction was to touch nothing \u2014 no keyboard, no mouse, no power button \u2014 because somebody was on the other end of all of it. A room full of computers being used by people who were not in the room."},"xr-desk-day-one":{slug:"xr-desk-day-one",date:"2023-01-05",dateLabel:"January 5, 2023 \xb7 10:30 a.m.",title:"Before anything was on it",caption:"My desk in the XR Lab in the first week of the job: two Dell panels on an arm, a keyboard, a Quest 2 and its controllers still factory-white, and Windows on the right-hand monitor twenty per cent of the way through a blue-screen restart. Everything in the rest of this chapter got built on top of this."},"xr-desk-assembled":{slug:"xr-desk-assembled",date:"2023-01-05",dateLabel:"January 5, 2023 \xb7 11:56 a.m.",title:"Eighty-six minutes later",caption:"The same desk, the same morning, eighty-six minutes after the photograph before it. A laptop with Unity open in the middle, three headsets spread across the surface, a tower under the desk, and both panels full. The lab ran at roughly this tempo for the next two years."},"xr-immersive-room":{slug:"xr-immersive-room",date:"2023-01-06",dateLabel:"January 6, 2023 \xb7 12:57 p.m.",title:"The projection wall",caption:"A curved projection wall down one side of the lab with a scene running across it, and a colleague out on the open floor in a headset, a controller in each hand. The point of the wall is that everyone else in the room can see what the person inside is seeing \u2014 which is the only practical way to argue about whether an interaction feels right."},"xr-printed-head-rig":{slug:"xr-printed-head-rig",date:"2023-01-11",dateLabel:"January 11, 2023 \xb7 3:08 p.m.",title:"A head that is not a head",caption:"A Quest 2 sitting on a printed stand with a controller balanced across it. The stand holds the headset upright and keeps its proximity sensor convinced that somebody is wearing it, so a build can run and be tested without pulling a headset on and off two hundred times a day. We printed our own tooling because nobody was selling it yet."},"xr-field-recorder":{slug:"xr-field-recorder",date:"2023-01-20",dateLabel:"January 20, 2023 \xb7 4:07 p.m.",title:"The recorder",caption:"A Zoom H1n held over a backlit laptop keyboard. Bought so we could capture our own source material rather than licence it, and the moment the audio work in this story came back around \u2014 four years of signal chain, pointed at spatial sound inside a headset."},"xr-studio-grows":{slug:"xr-studio-grows",date:"2023-02-27",dateLabel:"February 27, 2023 \xb7 5:04 p.m.",title:"The studio fills up",caption:"Late February 2023. The dev room has gone from one desk to a run of them down two walls: six panels lit, headsets parked at every station, a backpack on the floor, and one colleague still working with a driving scene up on her monitors. The team and the hardware grew at the same rate, which was fast."},"xr-studio-panorama":{slug:"xr-studio-panorama",date:"2023-03-07",dateLabel:"March 7, 2023 \xb7 2:15 p.m.",title:"The dev room, entire",caption:"A panorama of the whole dev room in the middle of the tower project: a profiler trace on the far-left panel, the tower scene, a build labelled PROTOTYPE, headsets at every seat \u2014 and, standing on the desk between two monitors, my own 3D printer. I brought it in to tinker with and never took it home.",wide:!0},"tower-in-engine":{slug:"tower-in-engine",date:"2023-04-03",dateLabel:"April 3, 2023 \xb7 12:06 a.m.",title:"Video memory exhausted",caption:"Not the project \u2014 what I did after it, on my own time, to find the ceiling. The same site rebuilt from scratch in Unreal Engine and pushed as far toward photoreal as I could take it: lattice mast, mounted dishes and drums, a service truck on the gravel pad, photoscanned rock underfoot and real foliage closing in. Along the top the engine is reporting that video memory has been exhausted, 546 MB over budget. Beautiful on a monitor, and completely undrivable by any headset of that generation \u2014 which was the thing I was trying to find out.",wide:!0},"stac-booth-build":{slug:"stac-booth-build",date:"2023-03-27",dateLabel:"March 27, 2023 \xb7 1:17 p.m.",title:"Building the booth",caption:"Setting up at the STAC conference the day before doors opened: two towers, a monitor running the tower scene, four Quests laid out along the table with wipes and sanitiser between them, and a colleague down on the floor sorting cable. A booth build is ninety per cent power and ten per cent everything else."},"stac-team":{slug:"stac-team",date:"2023-03-28",dateLabel:"March 28, 2023 \xb7 8:58 a.m.",title:"Climb with us",caption:"Three of us in front of the booth on the morning it opened. The screen behind reads *Climb With Us in Virtual Reality* \u2014 Mohawk College and Korol Contracting \u2014 and the orange board on the right is the pitch for The Ultimate Tower Experience. I am the one in the XR Developer shirt.",wide:!0},"stac-booth":{slug:"stac-booth",date:"2023-03-28",dateLabel:"March 28, 2023 \xb7 8:59 a.m.",title:"The booth",caption:"The same booth a minute later, from the aisle: headsets in a row on a skirted table, continuing-education banners on either side, and behind the drape a poster crediting the STAC committee. We were there to show an entire trade what its training might look like, and to advertise the college's brand new micro-credential in tower work."},"print-bed-batch":{slug:"print-bed-batch",date:"2023-03-09",dateLabel:"March 9, 2023 \xb7 8:57 a.m.",title:"A normal morning",caption:"A bed full of small black parts at nine in the morning \u2014 collars, bushings, threaded sockets, brackets \u2014 with a headset sitting behind the printer. Nothing here is a showpiece. This is what continuous printing actually looks like: an ordinary batch of the pieces something else needed in order to exist."},"makerspace-printers":{slug:"makerspace-printers",date:"2023-04-12",dateLabel:"April 12, 2023 \xb7 2:27 p.m.",title:"The makerspace catches up",caption:"A large-format printer alongside an enclosed Wanhao Duplicator, both parked on rolling tool chests in the college learning commons with students working at tables behind them. The makerspace improved dramatically across that year, and it changed what the XR Lab was able to ask for."},"printed-axe":{slug:"printed-axe",date:"2023-07-25",dateLabel:"July 25, 2023 \xb7 10:11 a.m.",title:"One very large axe",caption:"Holding a printed axe roughly as long as my arm span, in blue PLA, in the makerspace. It came off the bed in sections and was assembled afterwards. By this point the question had stopped being whether we could print a thing and become how large we felt like printing it."},"varjo-and-haptics":{slug:"varjo-and-haptics",date:"2023-03-31",dateLabel:"March 31, 2023 \xb7 11:34 a.m.",title:"Kit above the Quests",caption:"Shot off a monitor running a webcam capture: me with the phone up, and a colleague in a high-end headset and a haptic vest with the projection wall curving away behind. Hardware several tiers above the Quests, being tried out because it had arrived and somebody had to find out what it did."},"omni-treadmill":{slug:"omni-treadmill",date:"2023-06-19",dateLabel:"June 19, 2023 \xb7 12:45 p.m.",title:"The treadmill",caption:"An omnidirectional VR treadmill in the corner of the lab \u2014 harness ring, tracked base, low-friction plate, and the pair of special overshoes on the floor next to it. New tech came out, we bought it, and then we found out what it was actually good for by building on it."},"another-station":{slug:"another-station",date:"2023-04-25",dateLabel:"April 25, 2023 \xb7 2:55 p.m.",title:"Another station",caption:"A fresh triple-monitor corner desk, still on the default wallpaper, with a whiteboard behind it working through polyhexes on a grid. Empty stations kept appearing because people kept joining. This is what a department growing looks like from the inside."},"home-studio-2023":{slug:"home-studio-2023",date:"2023-04-18",dateLabel:"April 18, 2023 \xb7 7:50 p.m.",title:"Home, that spring",caption:"My room in April 2023: a light wood studio desk, monitors on stands either side of the panel, a DJ controller on a riser, a guitar in the corner, broadband absorbers on the walls, and a Quest sitting exactly where a microphone used to. The basement corner from 2012, eleven years and a great deal of better hardware later.",wide:!0},"ovin-robot-arm":{slug:"ovin-robot-arm",date:"2023-04-26",dateLabel:"April 26, 2023 \xb7 9:03 p.m.",title:"The OVIN garage",caption:"A robot arm the size of a building lifting a car over a facade whose doors read Testing Facility, Hangar Showroom, Garage and Track. Along the bottom the editor is warning that the mesh exceeds the polygon limit for a convex hull. The doors are labelled in plain words because the audience was eleven years old."},"ovin-islands":{slug:"ovin-islands",date:"2023-07-07",dateLabel:"July 7, 2023 \xb7 3:51 p.m.",title:"Islands",caption:"The shape of the OVIN experience: separate islands floating in a blue void \u2014 a gas station, the garage with its robot arm, and a sign carrying the OVIN and Ontario wordmarks \u2014 that you travel between rather than walk between. Built for the Ontario Vehicle Innovation Network to make the electric vehicle industry look like somewhere worth working.",wide:!0},"mohawk-camaro":{slug:"mohawk-camaro",date:"2023-06-22",dateLabel:"June 22, 2023 \xb7 11:09 a.m.",title:"Research trip",caption:"A Camaro ZL1 in Mohawk livery, up in the college automotive shop between the hoists with the rest of the fleet behind it. We were shown around the shop so the cars and engine parts in the experience could be modelled from real ones rather than approximated."},"ovin-engine-model":{slug:"ovin-engine-model",date:"2023-06-28",dateLabel:"June 28, 2023 \xb7 4:48 p.m.",title:"Every part, separately",caption:"An engine on screen mid-texturing, material library running along the bottom \u2014 headers, belts, pulleys, intake, alternator, all modelled as individual parts rather than as one object. It had to come apart, because a child in a headset was going to take it apart."},"quest-pyramid":{slug:"quest-pyramid",date:"2023-07-27",dateLabel:"July 27, 2023 \xb7 11:08 a.m.",title:"Enough for a classroom",caption:"Twenty-odd Meta Quest 2s, still sealed, stacked into a pyramid on the floor of the lab before anybody was allowed to open them. OVIN funded enough hardware to run a whole classroom at once, which is the difference between a demo and a programme."},"headset-cabinets":{slug:"headset-cabinets",date:"2023-06-19",dateLabel:"June 19, 2023 \xb7 12:45 p.m.",title:"Where they lived",caption:"The headsets in their cabinets \u2014 Mohawk-branded straps, hung in rows, charging. On top of the cabinets sit a printed skull, a moai and a Lego head, which is roughly the correct ratio of serious equipment to printer test pieces for a room like this one."},"vrto-2023":{slug:"vrto-2023",date:"2023-07-19",dateLabel:"July 19, 2023 \xb7 11:23 a.m.",title:"VRTO 2023",caption:"Marquee letters spelling VRTO 2023 on a polished floor, in a room overlooking a half-built Toronto tower and its crane. The other half of a job like this is going to see what everybody else is building, before you find out the hard way that you have built it too."},"chch-interview":{slug:"chch-interview",date:"2024-02-13",dateLabel:"February 13, 2024 \xb7 12:45 p.m.",title:"On camera",caption:"Being interviewed in front of a Mohawk IdeaWorks banner, camera on sticks, microphone held out on the end of an arm. We had made enough progress on the aircraft identification research that the local news came in to ask about it."},"research-team":{slug:"research-team",date:"2024-02-13",dateLabel:"February 13, 2024 \xb7 12:47 p.m.",title:"The research team",caption:"The team two minutes later, with the crew's camera still standing between us and the IdeaWorks and Engineering Technology banners on the wall. Applied research at a college looks like this: a meeting room, a handful of students, and a professor willing to point them at something genuinely hard.",wide:!0},"chch-lower-third":{slug:"chch-lower-third",date:"2024-02-13",dateLabel:"February 13, 2024 \xb7 6:51 p.m.",title:"Software Development Student",caption:"The broadcast that evening on CHCH, name and title along the bottom of the frame. Being made to explain the work to people outside it is its own useful test \u2014 a model you cannot describe in twenty seconds is a model you may not fully understand.",wide:!0},"chch-team-on-air":{slug:"chch-team-on-air",date:"2024-02-13",dateLabel:"February 13, 2024 \xb7 10:41 p.m.",title:"On air",caption:"The whole team on the broadcast, thumbs up in front of the IdeaWorks banner. A photograph of a television screen, which is still how most people keep a copy of anything.",wide:!0},"home-office-2025":{slug:"home-office-2025",date:"2025-01-07",dateLabel:"January 7, 2025 \xb7 3:59 p.m.",title:"The room, 2025",caption:"January 2025: two desks meeting in the corner, track lighting and an LED strip overhead, absorbers on the walls, a headset up on a shelf, a microphone on a boom arm, and a chart running on one panel while an editor runs on the other. Sixteen years on from the first build, and it is recognisably the same room, rebuilt."},"home-office-treadmill":{slug:"home-office-treadmill",date:"2025-01-07",dateLabel:"January 7, 2025 \xb7 11:18 p.m.",title:"Standing desk, treadmill under it",caption:"The same room later the same night, from the doorway: the second desk raised to standing height with a walking treadmill underneath it, and code up on the panel above. Most of the seven months of job applications happened in this room."},"mining-rig":{slug:"mining-rig",date:"2025-01-28",dateLabel:"January 28, 2025 \xb7 3:13 p.m.",title:"One sixty a day",caption:"Mining software running across two terminal panes with the dashboard overlaid on top: two active rigs, four active devices, an unpaid balance of one Canadian cent, and an estimate of CA$1.60 a day. Kept here at its true scale. It was never going to work. It was a refusal to sit still while nobody was answering."},"void-city":{slug:"void-city",date:"2025-03-12",dateLabel:"March 12, 2025 \xb7 12:49 p.m.",title:"Void",caption:"A city built out of coloured blocks seen from above, graded from violet through blue into green, with a single red marker somewhere near the middle of it. Work on the game **Void**, made in the gaps between job applications \u2014 because sending a hundred applications into silence needs an antidote.",wide:!0},"convocation-stage":{slug:"convocation-stage",date:"2025-06-19",dateLabel:"June 19, 2025 \xb7 3:10 p.m.",title:"Crossing the stage",caption:"Convocation, shot from up in the seats: gown on, crossing in front of the hooding party while the row behind waits its turn. Ten years after walking out of the first programme at George Brown."},"two-diplomas":{slug:"two-diplomas",date:"2025-06-19",dateLabel:"June 19, 2025 \xb7 4:24 p.m.",title:"Two diplomas",caption:"An hour later, in the lobby, holding both of them open under a screen reading Welcome to Mohawk College. Two programmes finished; three left before them. The order those happened in turned out to matter far less than I feared it would at nineteen."}},i=[{id:"first-build",era:"Summer 2009",railLabel:"2009",title:"The First Build",subtitle:"Thirteen years old, a pile of parts, and no instructions.",accent:"cyan",paragraphs:["The summer I was thirteen, I built a computer from scratch. Not a kit and not an upgrade \u2014 a bare case, a motherboard still in its anti-static bag, and the very specific terror of seating a processor for the first time with no idea whether the force you are applying is correct or catastrophic.","By the time that machine settled into its final form it carried 16 GB of RAM and an NVIDIA GeForce GTX 480, and mechanical drives with actual spinning platters inside them. You knew it was working because you could hear it and feel it through the desk.","It booted. That is the entire story, and it rearranged everything. A pile of components I had assembled on a carpet had become a working system that did what I asked it to. I have been chasing that exact feeling ever since, and every job I have held since is a version of it.","The only picture that survives from anywhere near this is a print, rephotographed years later: me on a couch with a laptop across my knees and my uncle beside me, almost certainly being shown whatever I had just worked out how to do. That is the posture the rest of this page is written in."],photos:["showing-my-uncle"]},{id:"salvage",era:"2009 \u2013 2014",railLabel:"Salvage",title:"The Salvage Years",subtitle:"If it was broken, free, or headed for the curb, I wanted it.",accent:"amber",paragraphs:["One build was never going to be enough, and I had no money. What I had instead was a reputation: I was the kid who would take your dead computer. Family, friends, friends of parents \u2014 when something stopped working it came to me rather than to the landfill.","I harvested all of it. Memory out of machines nobody wanted, optical drives, hard disks, fans, heatsinks, power supplies, expansion cards. A dead laptop was not a dead laptop. It was a stick of SODIMM, a 2.5-inch drive, a usable panel, and a copper heat pipe I could learn something from.","That habit taught me more than any course would have. You cannot fake your way through a teardown. Either you understand why the designer ran that trace there, routed that pipe that way, left exactly that much clearance \u2014 or the thing does not go back together and does not power on. I learned to read hardware the way you learn a language: by taking apart thousands of sentences somebody else wrote.","By 2014 I had moved past assembling other people's boards and started building circuits by hand. A transistor, an electrolytic capacitor, a trimmer pot, and an LED that lit on command. Modest, and a genuinely different category of thing \u2014 the first time I made electronics *do* something rather than making a computer work."],photos:["the-workbench","salvage-teardown","laptop-stripped-to-board","blood-and-thermal-paste","first-liquid-cooling","first-circuit-lit"]},{id:"the-den",era:"2012 \u2013 2014",railLabel:"The Den",title:"The Den",subtitle:"A basement corner that kept growing, photographed obsessively.",accent:"violet",paragraphs:["The setup was never finished. It was a living system, and I documented it compulsively across 2012 to 2014 \u2014 every photo below shot on the same Galaxy Note II \u2014 because I wanted a record of every single configuration it passed through.","It began as a corner: a television pressed into service as a monitor, a tower sitting on the carpet, a laptop running on the floor because there was no desk for it. Then a second panel. Then a third and a fourth. Then an L-shaped desk to carry more surface than sense. Then five displays lit simultaneously, all showing the same photograph of the same lake.","Every change was a decision about airflow, cable routing, sightlines and reach \u2014 the same class of constraint I now think about in software as latency, coupling and interface design. A closed loop went onto the CPU in December 2013 because air had stopped being enough. A discrete sound card went in five weeks later, and that card is the hinge in this whole story.","This is also the room I went to disappear into, and that is the honest version. Being immersed in electronics was the escape. It is the single thing in my life that has never once loosened its grip."],photos:["den-first-corner","four-screens-february","desk-condenser-mic","desk-goes-l-shaped","blue-hour-battlestation","the-den-september","the-wooden-desk","five-displays","the-sound-card","four-screens-may","the-den-panorama"]},{id:"lan-parties",era:"2012 \u2013 2014",railLabel:"LAN",title:"LAN Parties",subtitle:"The one night the hardware had an audience.",accent:"sky",paragraphs:["Every so often I would host a LAN party. Folding tables down the length of the basement, everyone hauling their own tower and monitor across town, six machines on one switch, food on paper plates, and a night that ran until the windows got light.","I hosted because I was the one with the hardware and the patience to make six different people's machines talk to each other. Somebody's network card would refuse to negotiate. Somebody's install would be corrupt. Somebody would arrive with a monitor and no cable for it. Solving all of that before the first match was, for me, the actual event.","Video games were the reason everybody came, and they were the thing that shaped what I thought I wanted. At that point I assumed, reasonably, that I would end up building them.","And it is worth saying plainly, because it explains everything that follows: I am a nerd at heart. Fan Expo in Toronto in August 2014, replica sword in hand, standing between cosplayers in full armour. The conventions, the comics, the games and the hardware were never separate interests. They were one impulse \u2014 find the thing you love and go all the way into it."],photos:["lan-new-years-eve","lan-in-the-dark","the-crew","fan-expo-sword","fan-expo-cosplay","fan-expo-jude"]},{id:"george-brown",era:"2015",railLabel:"Games",title:"Game Programming, George Brown",subtitle:"The obvious next step, and the first hard course correction.",accent:"rose",paragraphs:["Games had shaped me, so games looked like the answer. I enrolled in Game Programming at George Brown College, at the Casa Loma campus, in 2015.","One semester in, I read the syllabus properly and did the arithmetic. The program was built around browser-based games. In 2015 that was the wrong bet \u2014 the browser plugin era was visibly ending, and all of the momentum in the industry was in console and PC. I was being trained for a platform I believed was closing.","There was a second, less philosophical problem: I was commuting from Mississauga to Casa Loma. Hours a day on transit, to be taught something I had stopped believing.","So I left. It was the first time I made a decision of that shape \u2014 walking away from a credential because the substance behind it did not hold up to scrutiny. At the time it felt like failing. It was the opposite. It was the first time I trusted my own read of a technical trend over an institution's."],photos:[]},{id:"mohawk-it",era:"2015 \u2013 2016",railLabel:"IT",title:"Information Technology, Mohawk",subtitle:"Right industry, wrong seat.",accent:"orange",paragraphs:["Mohawk College, Information Technology. One semester, and a genuinely valuable one \u2014 a broad pass across computer engineering, networking and software that filled in the formal theory underneath everything I had taught myself by hand in a basement.","Then the destination came into focus and I did not want it. The path led to IT support: a career spent walking people who are not curious about technology through problems they have no interest in understanding. I loved the machines. The prospect of spending my life as the help desk between them and someone who resented them was genuinely infuriating.",'The realisation was sharper than "this is not for me." It was that I had mistaken *proximity* to technology for the work itself. Being near computers is not the same as building things with them. So I left Mohawk as well.',"Two programs, two exits, no credential, and I was nineteen. From the outside that reads as drift. From the inside it was the opposite of drift \u2014 I was declining to spend the next decade paying off a career I already knew I did not want."],photos:["hamilton-room"]},{id:"metalworks",era:"2016 \u2013 2020",railLabel:"Metalworks",title:"Metalworks: Synth Rider and M E R C S",subtitle:"Audio engineering, and the two names I released under.",accent:"fuchsia",paragraphs:["Metalworks Institute of Sound and Music Production \u2014 Audio Engineering and Digital Music Production. This is the one I finished, and it turned out to be the most rigorous technical education I had had to that point.","Signal chain. Gain staging. Compression, EQ, sidechaining, bus routing, phase relationships, headroom, and the difference between something being loud and something being *big*. It is systems engineering with your ears as the test suite. Debugging a mix that is somehow wrong is precisely debugging a system that is somehow wrong: isolate, bypass, solo, measure, and refuse to trust your own assumptions.","Walking into a room built from the floor up around the behaviour of sound will rearrange how you think. I loved that place. It opened up an entire discipline I had only been circling from the outside with a sound card and a condenser mic.","From 2016 to 2020 I worked as an audio engineer and music producer. First as **Synth Rider**, making retro and synthwave \u2014 neon, arpeggios and 1980s nostalgia rendered entirely in software. Later as **M E R C S**, moving into bass music, which is a harder, heavier, far more sound-design-driven discipline.","Most of that work is simply gone. MacBooks died and there was no budget for cloud storage, which is its own expensively-learned lesson about backups. What is scattered through the rest of this page is what survived, kept with whatever technical metadata came attached \u2014 because for this era that metadata *is* the documentation."],photos:["first-guitar","metalworks-studio-6","at-the-laptop"],tracks:["ocean-expressway","synth-rider-vocals"],clips:["studio-session-2015"]},{id:"humber",era:"2017 \u2013 2018",railLabel:"Humber",title:"Humber, in Parallel",subtitle:"General Arts and Science, majoring in philosophy, while the music ran.",accent:"amber",paragraphs:["While all of this was happening I was also enrolled at Humber College, from 2017 to 2018, in General Arts and Science with a major in philosophy. Two entirely separate lives running at once: late sessions in studios downtown, and coursework on argument, ethics and epistemology in the daytime.","It sounds like an odd pairing next to a production career, and it was the most useful thing I could have been studying. Philosophy is training in taking a claim apart to find the load-bearing assumption underneath it \u2014 which is the same move as a teardown, and the same move as debugging. It gave me a formal vocabulary for something I had been doing with a screwdriver since I was thirteen.","It also mattered later. When the decision about music arrived, I had spent two years being taught to interrogate my own reasoning rather than follow the momentum I was already carrying."],photos:[]},{id:"the-studios",era:"2018",railLabel:"Studios",title:"The Studios",subtitle:"One we built ourselves, and one hidden above a row of shops on Queen Street.",accent:"violet",paragraphs:["Two rooms defined 2018.","The first, my dad and I built. He had moved into a new house and the basement room was bare cinderblock. I had just come out of Metalworks with a head full of room acoustics, so we did it properly rather than taping foam to a wall: bass traps in all four corners, broadband absorption on the walls, clouds overhead, acoustic insulation and matting layered behind *and* in front of the drywall, ducting run on the diagonal so sound could not travel straight out through the vents, and jambs fitted to the doors so the seals actually sealed. Then we balanced the monitors to the room itself. Building a studio with my father, using knowledge I had gone away to get, is still one of the things I am proudest of.","The second was **669** on Queen Street \u2014 named, as far as any of us knew, for its own street number. Three floors of studios stacked above a row of storefronts, run at the time by an engineer everyone just called Dot. We always booked Room 2. From the pavement it was completely anonymous; nobody walking past had any idea what was up there. The twenty-four-hour convenience store across the road probably had it figured out, given how many of us came through at four in the morning once everything else on the strip had shut.","It was also walking distance from **APT 200**, the hip-hop bar that was the pre-party and the after-party whenever an artist was in town that year. It is where a lot of the Toronto scene of that moment passed through, and where some of the people who went on to real recognition were still just around.",'The Saturday booking became a fixture that autumn \u2014 and the archive proves it better than my memory does. The photograph below from Room 2 was taken at 11:46 p.m. on Saturday, 8 September 2018. The session bounce filed as "She" is from that same night. Two files that survived on completely different devices, reunited by their timestamps.'],photos:["the-purple-studio","studio-669-lounge","studio-669-sept-8","studio-669-sept-22"],tracks:["session-she","session-sept-15","sketch-sept-28"],clips:["the-light-promo"]},{id:"los-angeles",era:"December 2018",railLabel:"LA",title:"Los Angeles",subtitle:"Flown out to work, and the trip where I decided to stop.",accent:"rose",paragraphs:["Around December 2018 the studio work connected me to **Daxz** \u2014 Jahmar Carter \u2014 a producer who has worked with Drake. He flew me out to Los Angeles to work across a handful of studios and projects for a short stretch.","I could not get over it. My first evening out there I stood in an In-N-Out parking lot under palm trees and it landed properly: somebody else was paying for me to be here, to make music. It felt like arriving. Like the goal I had been walking toward had actually turned up.","The work was real and the rooms were extraordinary \u2014 one panorama below was taken at half past five in the morning with everybody still going, a friend from high school who had taught himself to produce, a friend from music school working in bass, and a rapper from home all out there with us.","And it was on that same trip, toward the end of it, that I decided to finish at Humber and start moving out of music as a full-time career.","The reason was the shape of the industry rather than the work. It runs on being cut-throat, and I am not a cut-throat person. The lifestyle wrapped around it \u2014 the parties, the drugs, the whole rockstar apparatus \u2014 was simply not something I could see myself surviving for long, let alone building a life on. Sitting in the middle of the thing I had wanted, I could see clearly that wanting it had not made me suited to it.","So I walked, for the third time, and this is the one I am most glad about. It is the same decision I had made at George Brown and at Mohawk, and by then I had learned to trust it: leaving something that is working on paper because you can see what it costs."],photos:["in-n-out-la","la-studio-night"]},{id:"back-to-software",era:"2020 \u2192",railLabel:"2020",title:"Back to Software, and the Markets",subtitle:"The lockdowns hand me two new obsessions.",accent:"emerald",paragraphs:["Deciding in Los Angeles was not the same as stopping. I finished at Humber, and the music wound down across 2019 and into 2020 rather than ending at a stroke \u2014 still engineering, still producing, but no longer building a life around it. COVID closed the venues and ended the sessions outright, and I let **M E R C S** go there rather than watch it thin out any further.","With the music set down, I went back to school for Software Development \u2014 the thing I had been circling since I was thirteen, approached properly this time, with a decade of hardware intuition and four years of signal-chain discipline behind it.","The setup came along too. The 2020 photograph is the same instinct as 2009, eleven years later: a chair worth sitting in, a studio monitor on a stand, acoustic treatment on the wall, a boom arm still within reach. Different hardware entirely, identical person.","The other thing the lockdowns handed me was the market. The COVID crash was the first time I watched a system that large break in real time, and I wanted the mechanics rather than the headlines. That turned into self-directed investing through Wealthsimple and a durable interest in markets as systems \u2014 incentives, liquidity and feedback loops, which is not so far from anything else I have taken apart on a folding table.","The pattern, if there is one: I have spent my life escaping into electronics, and every apparent detour \u2014 games, IT, music, markets \u2014 turned out to be another lens on the same subject. None of it was wasted. All of it is load-bearing."],photos:["setup-2020"]},{id:"the-hand-coded-years",era:"2021 \u2013 2022",railLabel:"School",title:"The Hand-Coded Years",subtitle:"Remote school, browser tabs, and learning one error at a time.",accent:"sky",paragraphs:["School was fully remote. There was no classroom to disappear into and no instructor a few desks away to ask when the code stopped making sense. My main sources of help were Stack Overflow and W3Schools: search, read, try, break it, read again, and eventually understand why the fix worked.","LLMs were not part of the workflow yet. Everything was still coded by hand, and that constraint mattered. I had to sit with the syntax, trace the error, and build a mental model instead of asking a machine to produce a plausible answer. The browser became the second monitor in the learning process: documentation, examples, assignment requirements, and the application all open together.","The photograph from February 23, 2022 is a small record of that process. It is not a polished project screenshot; it is the desk while the work was happening. Code on one side, the result on the other, and enough tabs open to show how much of programming at that stage was investigation."],photos:["hand-coded-learning-2022"]},{id:"ideaworks",era:"2022 \u2013 2023",railLabel:"IdeaWorks",title:"IdeaWorks",subtitle:"A floor full of desks nobody was allowed to touch.",accent:"orange",paragraphs:["Before the XR job there was a short stint at **IdeaWorks**, Mohawk's applied research office, supporting the manager of funding proposals. It was administrative work sitting right at the edge of interesting work: reading what other people were proposing to build, and watching how they argued for the money to build it.","The floor looked like the photograph below and almost always did. Most of the developers remoted into those cubicles from home, so the machines were awake and the chairs were empty. The instruction was to touch nothing \u2014 not a keyboard, not a mouse, not a power button \u2014 because somebody was on the other end of every one of them.","The photograph carries a timestamp of 26 January 2023, a few weeks after I had already moved across to the XR Department. The floor had not changed. It never really did."],photos:["ideaworks-cubicles"]},{id:"xr-lab",era:"January 2023",railLabel:"XR Lab",title:"Into the XR Lab",subtitle:"Nobody was teaching this yet, which turned out to be the point.",accent:"violet",paragraphs:["In January 2023 I landed a job in Mohawk College's XR Department as an XR Developer. Because of what XR is and what it runs on \u2014 headsets, tracked controllers, depth cameras, motion rigs, machines strong enough to drive all of it \u2014 the work had to happen in the building. This was still the tail end of the era when everything else had gone remote, and we were required on site. I did not mind for a second.","The first two desk photographs below are eighty-six minutes apart. At half past ten in the morning there is a bare surface, two Dell panels, a Quest 2 still factory-white, and Windows on the right-hand monitor a fifth of the way through a blue-screen restart. By 11:56 there is a laptop with Unity open, three headsets, a tower underneath and both panels full. That is the tempo of the place in one morning.","There was no formal education in any of it. XR was new enough that nobody was teaching it, so everything came out of Unity's own documentation, the SDK notes from whoever built the device, forum threads and a very great deal of YouTube. It became obvious extremely quickly that the one differentiating skill was whether you could teach yourself something properly and fast. That was the job. That was the whole job.","For the same reason there was nobody in the department with ten years of experience to sit beside \u2014 there was no such person anywhere. Everyone was new to it, including the people selling us the hardware. New kit would come out, we would buy it, and we would find out what it could do by building something with it. It genuinely felt like being early.","The physical side mattered as much as the code. The lab had 3D printers that were advanced for the time, which meant we could make the objects a mixed-reality scene needed instead of designing around whatever could be bought. That extended to our own tooling: the printed rig below holds a headset upright and keeps its proximity sensor convinced somebody is wearing it, so a build can be run and tested without pulling a headset on and off two hundred times a day.","And then the music came back. Making spatial audio behave \u2014 binaural, properly directional, tracking correctly against head rotation so a sound stays where the world put it when you turn your head \u2014 is the same discipline as four years at Metalworks and in rooms on Queen Street, aimed at a different output. Alongside one other developer I became the person the department came to for anything audio-related. The handheld recorder in the photograph from 20 January is a Zoom H1n, bought so we could capture our own source material rather than licence it."],photos:["xr-lab-whiteboard-2023","xr-desk-day-one","xr-desk-assembled","xr-immersive-room","xr-printed-head-rig","xr-field-recorder"]},{id:"cell-tower",era:"January \u2013 March 2023",railLabel:"Tower",title:"The Ultimate Tower Experience",subtitle:"They recommended we climb one first.",accent:"cyan",paragraphs:["The department's first major project was a VR cell tower simulator, built with **Korol Contracting**. The industry had a recruitment problem: climbing towers is a specialised, dangerous, well-paid trade that very few people were entering, and the training pipeline behind it is long and expensive. The hope was that an experience could do two jobs at once \u2014 pull the right people in, and let the wrong people find out early, safely and cheaply, that they did not want to be three hundred feet up a lattice.","So it was recommended that the developers climb one. Not a three-hundred-foot mast \u2014 Korol's indoor training tower, which is more than enough to make the point. Harness on, clipped in, actually up it. The video below is a colleague starting his first climb on 27 January 2023, with the rest of us filming from the floor. You cannot fake the part that matters: what the rungs do to your hands, what your body does when you look down, exactly where the fear arrives. That was the thing we were being asked to reproduce.","Then we built it. A harness mapped onto a virtual body, hands that would wrap a rung instead of clipping straight through it, and the industry's safety procedure built into the sequence rather than bolted on at the end.","At the end of March we took it to the **STAC** conference and put it in front of the industry. The screen read *Climb With Us in Virtual Reality*, and next to it we were advertising the college's brand new micro-credential in tower work. Three of us, a skirted table, a stack of Quests and a lot of sanitising wipes, showing an entire trade what its training might look like.","The last photograph below is not from the project. Once the thing had shipped I wanted to know what the same site would look like with the realism turned all the way up, so I rebuilt it in **Unreal** on my own time \u2014 photoscanned rock, real foliage, a lit sky, the service truck on the pad. Along the top the engine is reporting that video memory has been exhausted, 546 MB over budget. It was extraordinary on a monitor and no headset of that generation could have driven it for a second, which was the answer I had gone looking for."],photos:["xr-studio-grows","xr-studio-panorama","stac-booth-build","stac-team","stac-booth","tower-in-engine"],clips:["tower-climb-training"],links:[{label:"The cell tower simulator",to:"/CellTower"}]},{id:"raethexn",era:"March \u2013 June 2023",railLabel:"Raethexn",title:"Raethexn Technologies",subtitle:"Founded as an XR studio, and run in the evenings alongside the day job.",accent:"sky",paragraphs:["I founded **Raethexn Technologies** in 2023, and it started as an XR company. The premise was the one the tower had already proved: training that is expensive, slow or genuinely dangerous to run for real can be rehearsed in a headset instead, and somebody has to build those. Everything below ran in parallel with the college work, in evenings, and none of it was Mohawk's.","The first thing was a climbing experience of my own. A room fills with water. You climb to stay above it. That is the whole mechanic, and it turns out to be enough.","It came out of **Physical: 100**, which was airing that winter \u2014 and not for the reason you would guess. Building the tower had taught me something nobody warns you about: climbing in VR means holding your arms above your head, hand over hand, for minutes at a time, and it is genuinely hard work. Ten minutes in a headset and your shoulders know about it the next day. The show was built entirely around that kind of endurance, so the shape it suggested \u2014 a physical trial, a rising clock, no way out but up \u2014 was one the medium was already good at without anybody having noticed.","The first clip below is the water being built in the editor, untextured and flat orange, pouring out of a duct with the ladder already standing in the corner. The second is five days later, from inside the headset, one hand closed on a rung in the dark.","By June there was a real one: a workplace-training demo for **Purolator**, which is the studio doing the thing it was founded to do rather than a proof to myself that it could. The company has changed shape a great deal since \u2014 it is where the AI and memory work lives now \u2014 but it started here, with a headset and a training problem."],photos:[],clips:["flood-room-water-sim","flood-room-in-headset","purolator-training"]},{id:"printers",era:"March \u2013 July 2023",railLabel:"Printers",title:"Printers, Prints, and a Lab That Kept Growing",subtitle:"I brought my own printer in and never took it home.",accent:"amber",paragraphs:["Somewhere in the middle of the tower project my interest in 3D printing stopped being a hobby. I brought my own printer into the dev lab \u2014 it is sitting on the desk in the panorama in the tower chapter, between a monitor running the editor and a monitor running the tower \u2014 and printed more or less continuously: jigs, mounts, controller adapters, headset stands, props for scenes, and a long tail of things that existed purely because I wanted to know whether they would come off the bed.","The photograph from the morning of 9 March is a full plate of small black parts. That is a normal run, not a special one.","The college's makerspace grew alongside the lab. By April there was a large-format machine and an enclosed Wanhao parked on tool chests out in the learning commons, and by July we could produce genuinely large objects \u2014 the axe I am holding in the photograph from 25 July came off a bed in sections and was assembled afterwards.","We also built for the lab itself. The vertical screen in the video below stood in the corner on castors with a Kinect depth camera bolted to the top of it, and I made small experiences for it: a screensaver that noticed you and reacted. Nobody asked for that. It got built because the hardware was sitting there.","Everything kept arriving. An omnidirectional treadmill. Headsets several tiers above the Quests, with haptic vests to go with them. Another triple-monitor station going in because another person had joined. The setup at home moved in step \u2014 the photograph from 18 April is my room that spring, with a Quest sitting exactly where a microphone used to."],photos:["print-bed-batch","makerspace-printers","printed-axe","varjo-and-haptics","omni-treadmill","another-station","home-studio-2023"],clips:["kinect-kiosk"]},{id:"ovin",era:"April \u2013 July 2023",railLabel:"OVIN",title:"OVIN",subtitle:"Same tools, audience aged eleven.",accent:"emerald",paragraphs:["The next project was **OVIN** \u2014 the Ontario Vehicle Innovation Network. Where the tower experience was aimed at adults choosing a trade, this one was aimed at children, and the goal was simple: make the electric vehicle industry look like somewhere you would want to work.","It was built as a set of islands floating in a void that you travel between rather than walk between \u2014 a gas station, a garage with a robot arm swinging over it, a testing facility, a hangar showroom, a track. Doors labelled in plain words, because the audience was eleven.","The research for it was the best part of the job. We were given a tour of Mohawk's aircraft hangar so the hangar in the experience could be a real one \u2014 the video below is from inside it, looking out at the airfield \u2014 and a tour of the automotive shop, where the college keeps a Camaro in its own livery up between the hoists. The engine in the photograph is what came out of that second visit: every part modelled and textured separately, because a child in a headset was going to pull it apart.","Because it was built for classrooms, OVIN funded enough hardware to run a whole room at once. Twenty-odd Quest 2s arrived in July and I stacked them into a pyramid on the floor before anyone was allowed to open them, which I regret nothing about. After that they lived in cabinets, charging in rows.","We went to **VRTO** in Toronto that July as well, which is the other half of a job like this: going to see what everybody else is building, before you find out the hard way that you have built it too."],photos:["ovin-robot-arm","ovin-islands","mohawk-camaro","ovin-engine-model","quest-pyramid","headset-cabinets","vrto-2023"],clips:["hangar-tour"],links:[{label:"The OVIN experience",to:"/OVIN"}]},{id:"research",era:"2023 \u2013 2024",railLabel:"Research",title:"Applied Research, and the Local News",subtitle:"Training a model from scratch, on one machine, with nobody to ask.",accent:"sky",paragraphs:["Across that year the role changed shape. New students kept joining the team and mentoring them became a real part of what I did \u2014 which is a strange thing to be doing eighteen months after teaching yourself the subject off YouTube, and also the fastest way I know to find out what you actually understand.","Eventually my own coursework won. I dropped to part-time in the lab, which was the right call and still felt like a loss. But it opened the next door: I found I could substitute credits for applied research, and I took it.","The project, with **Professor Steven Adams**, was to train a model from scratch to identify aircraft from photographs \u2014 first that there was an aircraft in the frame at all, then which aircraft it was. *From scratch* means what it says: no cloud, no pretrained backbone handed to us, no course to follow.","Two things we learned in the first few months are things I now take entirely for granted. The first is how much data a model like that actually needs, which is always an order of magnitude past whatever you assumed. The second is what a GPU does to training time. Moving the work onto one cut our iteration time by something close to a factor of ten \u2014 and a factor of ten is not a speed-up, it is a different research process, because you can suddenly afford to be wrong.","We made enough progress that the local news came in to interview us. The photographs from 13 February 2024 are that afternoon: the crew setting up in a meeting room, the team, and a lower third on CHCH with my name on it reading *Software Development Student*.","This is where the AI work started for me properly. Everything I do now runs off it."],photos:["chch-interview","research-team","chch-lower-third","chch-team-on-air"],links:[{label:"Aircraft identification",to:"/AircraftIdentifierAI"},{label:"Machine learning projects",to:"/MachineLearningProjects"}]},{id:"the-bot",era:"2023 \u2013 2025",railLabel:"The Bot",title:"Trying to Replace My Sister With a Chatbot",subtitle:"A joke that turned into a job.",accent:"fuchsia",paragraphs:["At the same time I was taking an introductory AI course at the college, and my sister was working as a real estate agent. I thought it would be funny to try to automate her.","This was early. ChatGPT was effectively the only game in town, the chat interface itself was brand new, and almost all of my work was against the API rather than a product. I built a bot that could hold a conversation as a real estate agent: work out what somebody actually wanted, answer questions about listings, stay in character while doing it.","It was a joke and then it was not. It caught the attention of **basl.ai**, a knowledge-management company working in real estate who already held the licence the thing would have needed anyway, and they hired me to keep building it \u2014 specifically to wire it into live listing data so it was answering from the market rather than from its training set. That is the entire problem with these systems in one sentence, and I was very lucky to be pointed straight at it in 2023."],photos:[],links:[{label:"The real estate bot",to:"/RealEstateBot"},{label:"Engineering at basl.ai",to:"/BaslEngineer"}]},{id:"the-lean-year",era:"2025",railLabel:"2025",title:"Seven Months",subtitle:"The startup sinks, the market shuts, and I do whatever works.",accent:"rose",paragraphs:["By early 2025 school was ending and so was the startup. There was no budget to keep me on, and not long afterwards the company itself began to go under. My read, for what it is worth, is scope creep with no go-to-market underneath it \u2014 an enormous amount of product built for a customer nobody had gone out and found. I did at least get several friends from college hired there before it went, which remains one of my favourite things I have done.","Then the job market. The AI boom was in full swing and the entry level was brutal. It took seven months to find work in my field, and seven months is a long time to be told nothing at all.","So I did what I have done at every other point in this story, which is learn something and try to make it pay. One of those things was turning my machine into a crypto miner. The screenshot below is honest about the scale of it: two rigs, four devices, an estimate of one dollar sixty a day. It was not a plan. It was a refusal to sit still.","Another was going back to making visuals for DJs \u2014 programmatically this time, driven by the audio itself, which quietly pulled the music years, the graphics work and the code into one thing. The clip below is that running on a monitor in March 2025.","And to break up the applications I worked on a game, **Void**. It was already running before any of this started \u2014 the playthrough below was recorded in December 2024 \u2014 but sending a hundred applications into silence needs an antidote, and it became one.","In June I finished my last outstanding course and graduated with two diplomas. The last two photographs are that day: crossing the stage, and standing in the lobby afterwards holding both of them open."],photos:["home-office-2025","home-office-treadmill","mining-rig","void-city","convocation-stage","two-diplomas"],clips:["void-playthrough","generative-visuals"],links:[{label:"Void",to:"/Games/Void"}]},{id:"clarity",era:"July 2025 \u2192",railLabel:"Clarity",title:"Clarity",subtitle:"AI engineer \u2014 which is every previous chapter running at once.",accent:"cyan",paragraphs:["In July 2025 I started at **Clarity** as an AI engineer, seven months after I began looking.","That is the story so far. A thirteen-year-old on a carpet with a motherboard. A teenager taking apart other people's dead laptops because he could not afford new ones. Four years spent working out why a mix was somehow wrong. A philosophy course at night. A studio built with my father out of bare cinderblock. A college lab where nobody yet knew how any of it worked. A model trained from scratch on one GPU.","None of it was planned. All of it turned out to be the same subject."],photos:[]}],r=e=>i.find((t=>t.id===e)),s=[{slug:"ocean-expressway",title:"Ocean Expressway",alias:"Synth Rider",when:"2017",duration:395,source:"MP3, 44.1 kHz / 265 kbps",note:"The one file that survived with its metadata fully intact \u2014 tagged as Synth Rider, genre synthwave, released 2017 as a single. Six and a half minutes, which tells you it was built to be driven to.",attribution:"tagged"},{slug:"synth-rider-vocals",title:"Synth Rider \u2014 vocal version",alias:"Synth Rider",when:"Synth Rider era",duration:220,source:"MP3, 44.1 kHz / 192 kbps",note:"A vocal take, recovered from a video export rather than a session file \u2014 the encoder chain is still visible in the file header. The original project is gone.",attribution:"filename"},{slug:"session-she",title:'Studio Session \u2014 "She"',alias:null,when:"Saturday, September 8, 2018",duration:234,source:"MP3, 44.1 kHz / 128 kbps",note:"A rough bounce off the end of a Saturday session, named for the vocal it was built around. Bounced at 128 kbps because it was only ever meant to be a reference on the drive home. The photograph of Room 2 above was taken at 11:46 p.m. that same night.",attribution:"filename"},{slug:"session-sept-15",title:"Studio Session \u2014 September 15",alias:null,when:"Saturday, September 15, 2018",duration:175,source:"MP3, 44.1 kHz / 128 kbps",note:"The following Saturday. Between the bounces and the photographs, four consecutive weekends of September 2018 are documented \u2014 the 8th, the 15th, the 22nd and the 28th. That is the only stretch of the whole era with a real paper trail.",attribution:"filename"},{slug:"sketch-sept-28",title:"Sketch \u2014 September 28",alias:null,when:"September 28, 2018",duration:42,source:"WAV, 44.1 kHz / 16-bit",note:"Forty-two seconds. An idea captured before it evaporated and never taken further. Most production work looks like this and almost none of it is ever kept.",attribution:"filename"},{slug:"night",title:"Night",alias:null,when:"Unknown, 2016 \u2013 2020",duration:175,source:"WAV, 192 kHz / 32-bit float",note:"Rendered at 192 kHz in 32-bit float \u2014 four times the sample rate anything needs for delivery. That is a mastering-stage export, which means at some point this one mattered enough to render properly.",attribution:"unattributed"},{slug:"rrp",title:"RRP",alias:null,when:"Unknown, 2016 \u2013 2020",duration:405,source:"WAV, 44.1 kHz / 32-bit float",note:"The longest surviving piece at six minutes forty-five, kept in 32-bit float, which means it was still live in the mix rather than finished. What the initials stood for is lost.",attribution:"unattributed"},{slug:"demo-blind",title:'Demo \u2014 "Blind"',alias:null,when:"Unknown, 2016 \u2013 2020",duration:255,source:"WAV, 44.1 kHz / 32-bit float",note:"Filed as a demo, in floating point, at full length. A track that made it to the stage of being shown to someone.",attribution:"unattributed"},{slug:"bp",title:"BP",alias:null,when:"Unknown, 2016 \u2013 2020",duration:212,source:"WAV, 48 kHz / 24-bit",note:"The only survivor rendered at 48 kHz / 24-bit \u2014 the video and broadcast standard rather than the music one. Possibly cut for picture.",attribution:"unattributed"},{slug:"pre-master",title:"Pre-Master",alias:null,when:"Unknown, 2016 \u2013 2020",duration:246,source:"WAV, 44.1 kHz / 16-bit",note:"Named for its position in the chain rather than for itself: the mix as it stood immediately before mastering. Which record it belonged to is unrecoverable.",attribution:"unattributed"},{slug:"untitled-110",title:"Untitled",alias:null,when:"Unknown, 2016 \u2013 2020",duration:110,source:"WAV, 44.1 kHz / 32-bit float",note:"One minute fifty, floating point, no title and no date. It survived in two formats on the same drive, which suggests it was bounced to be sent somewhere.",attribution:"unattributed"}],h=[{slug:"studio-session-2015",title:"Studio session",when:"November 24, 2015",duration:"0:23",note:"Shot handheld at 10 p.m. on a Tuesday: a spectrum analyser running on the left panel, the mixer open on the right, a pad controller lit up under my hands. This predates Metalworks \u2014 it is the evidence that the music had already started before I found the school for it."},{slug:"the-light-promo",title:'"The Light" \u2014 promo',when:"Synth Rider / M E R C S era",duration:"0:30",square:!0,note:"A thirty-second square promo cut for social, built around a featured vocalist, finished with chromatic aberration and analogue-video artefacting. Made in the era when a release meant you also shot and cut the trailer yourself."},{slug:"tower-climb-training",title:"First climb",when:"January 27, 2023 \xb7 9:39 a.m.",duration:"0:47",portrait:!0,note:"A colleague starting his first climb on Korol's indoor training tower \u2014 harnessed, clipped in, working up the lattice past the cable run \u2014 with the rest of us filming from the floor. The recommendation was that the developers climb one before building the experience, and it was the right recommendation. You cannot reproduce what you have not felt."},{slug:"flood-room-water-sim",title:"The water, in the editor",when:"March 8, 2023 \xb7 10:23 p.m.",duration:"0:22",portrait:!0,note:"Shot off a laptop screen late at night: the flood itself, still untextured, pouring out of a duct near the ceiling and spreading across the floor in flat orange. The ladder is already standing in the scene on the left, because the ladder was the design \u2014 the water rises and the only direction left is up."},{slug:"flood-room-in-headset",title:"Climbing, from inside the headset",when:"March 13, 2023 \xb7 10:45 p.m.",duration:"0:11",square:!0,note:"Five days later, captured from inside a Quest: a tracked hand closed on the rung, the ladder running up out of frame, racking and pipework in the dark on either side. Eleven seconds is enough to know whether a climb feels like a climb."},{slug:"purolator-training",title:"Purolator workplace training",when:"June 9, 2023",youtubeId:"cVkQ1PhlYsA",note:"A VR workplace-training demo for **Purolator**, and the clearest surviving picture of what Raethexn was set up to do in 2023: take the training that is expensive, slow or hazardous to run for real, and rehearse it in a headset instead. The recording turned up years later in Google Drive, too large to sit in this archive with everything else, so it lives on YouTube."},{slug:"void-playthrough",title:"Void \u2014 playthrough",when:"December 2024",youtubeId:"1FKdzQ8HbpU",note:"A full run through the alpha, recorded before the seven months of applications had properly begun \u2014 which is the honest date on Void. It was already underway when the job market closed; it just became far more useful to have afterwards."},{slug:"kinect-kiosk",title:"The lab screensaver",when:"April 13, 2023 \xb7 9:19 a.m.",duration:"0:34",portrait:!0,note:"A tall screen on castors in the corner of the lab with a Kinect depth camera bolted to the top of it, running a rendered figure inside a lit box. I built small experiences for this one because the hardware was sitting there and nobody had asked me not to."},{slug:"hangar-tour",title:"Inside the hangar",when:"June 21, 2023 \xb7 10:28 a.m.",duration:"0:27",portrait:!0,note:"Mohawk's aircraft hangar during the OVIN research trip \u2014 a wing in the foreground, insulated wall panels overhead, and the door standing open onto the apron with the airfield and a control tower beyond it. We were shown around so the hangar in the experience could be modelled from a real one."},{slug:"generative-visuals",title:"Visuals, generated",when:"March 1, 2025 \xb7 5:12 p.m.",duration:"0:08",portrait:!0,note:"Audio-reactive visuals running full-screen beside a column of preset names, in the middle of the seven months of job applications. Producing visuals for DJs was work I had done years earlier by hand; doing it programmatically pulled the music, the graphics and the code into a single thing."}],d=["night","rrp","demo-blind","pre-master","bp","untitled-110"],l=[{value:"2009",label:"First build, from scratch"},{value:"13",label:"Years old when it booted"},{value:"73",label:"Photographs recovered"},{value:"11",label:"Tracks that survived"}]}}]);
//# sourceMappingURL=922.13b22e80.chunk.js.map